from uuid import uuid4

from app.llm.interfaces import LLMRequest, LLMResponse
from app.schemas.enums import ModelExecutionStatus, ReportStatus, SourceKind
from app.schemas.report import DraftReport, GenerationMetadata, ReportSection

SYNTHETIC_BANNER = (
    "SYNTHETIC DRAFT REPORT — generated by a mock LLM template. "
    "Not clinically validated. A veterinary radiologist must review the original study. "
    "Missing findings do not confirm absence of disease."
)


class MockLLMProvider:
    provider_id = "mock-llm"
    model_id = "mock-report-generator"
    model_version = "0.1.0"

    def generate(self, request: LLMRequest) -> LLMResponse:
        gen = request.generation
        cited = [f.finding_id for f in gen.findings]
        doc_note = ""
        if gen.document_context_file_count > 0:
            doc_note = (
                f" Document context: {gen.document_context_file_count} file(s) "
                "available as draft text only (paths omitted)."
            )
        technique = ReportSection(
            text=(
                f"{SYNTHETIC_BANNER}\n\n"
                f"Technique (metadata only): species={gen.species.value}, "
                f"modality={gen.modality.value}, region={gen.anatomical_region.value}. "
                f"No DICOM pixels were reconstructed or interpreted.{doc_note}"
            ),
            cited_finding_ids=[],
        )
        if gen.execution_status == ModelExecutionStatus.UNSUPPORTED:
            findings_text = (
                f"{SYNTHETIC_BANNER}\n\n"
                "Automated imaging pipeline is unsupported for this case. "
                "No mock vision findings were produced for clinical use."
            )
            impression_text = (
                f"{SYNTHETIC_BANNER}\n\n"
                "Impression: case flagged for manual veterinary radiologist review. "
                "No automated impression is offered."
            )
            recs = (
                "Manual review of the original imaging study by a veterinary radiologist. "
                "Do not use this draft for clinical decisions."
            )
        elif gen.execution_status == ModelExecutionStatus.FAILED:
            findings_text = f"{SYNTHETIC_BANNER}\n\nMock vision execution failed. No imaging findings are available."
            impression_text = f"{SYNTHETIC_BANNER}\n\nImpression cannot be generated because the imaging adapter failed."
            recs = "Re-run analysis after investigating the adapter failure. Expert review is still required."
        elif gen.no_findings_returned or not gen.findings:
            findings_text = (
                f"{SYNTHETIC_BANNER}\n\n"
                "The mock imaging adapter returned no findings. "
                "This is not a statement that the study is normal."
            )
            impression_text = (
                f"{SYNTHETIC_BANNER}\n\n"
                "Impression: no structured mock findings were returned. "
                "Absence of disease is not confirmed."
            )
            recs = "Veterinary radiologist review of the complete study is required before any clinical conclusion."
        else:
            bullets = "\n".join(
                f"- [{f.finding_code}] {f.description} (status={f.finding_status.value}, location={f.anatomical_location})"
                for f in gen.findings
            )
            findings_text = f"{SYNTHETIC_BANNER}\n\nReported mock findings:\n{bullets}"
            impression_text = (
                f"{SYNTHETIC_BANNER}\n\n"
                "Impression: mock structured findings are listed above as suspected/uncertain items only. "
                "They must not be copied into a final clinical report without radiologist review."
            )
            recs = (
                "1. Veterinary radiologist review of source images (when available).\n"
                "2. Confirm or reject each cited mock finding ID.\n"
                "3. Do not treat unlisted anatomic regions as disease-free."
            )

        rag_block = ""
        used_passages = []
        used_ids: list[str] = []
        if gen.rag_passages:
            # Deterministic "used" subset — not all retrieved passages are cited (ISS-RAG-04).
            take = max(1, min(2, len(gen.rag_passages)))
            for idx, p in enumerate(gen.rag_passages[:take]):
                related = [cited[idx % len(cited)]] if cited else []
                used = p.model_copy(update={"related_finding_ids": related})
                used_passages.append(used)
                used_ids.append(p.source_id)
            lines = [
                f"- [{p.source_id}] {p.title} / {p.section} (score={p.score}): {p.passage[:180]}…"
                if len(p.passage) > 180
                else f"- [{p.source_id}] {p.title} / {p.section} (score={p.score}): {p.passage}"
                for p in used_passages
            ]
            unused = len(gen.rag_passages) - len(used_passages)
            rag_block = (
                "\n\nOptional demo RAG context (used passages only — not clinical evidence):\n"
                + "\n".join(lines)
            )
            if unused:
                rag_block += f"\n({unused} retrieved passage(s) not cited in this mock draft.)"
            recs = f"{recs}\n4. Review listed RAG demo passages; do not treat them as proof of findings."

        report = DraftReport(
            report_id=f"rpt-{uuid4().hex[:12]}",
            case_id=gen.case_id,
            status=ReportStatus.DRAFT,
            generation=GenerationMetadata(
                provider_id=self.provider_id,
                model_id=self.model_id,
                model_version=self.model_version,
                source_kind=SourceKind.MOCK,
                synthetic=True,
                clinically_validated=False,
            ),
            technique=technique,
            findings=ReportSection(text=findings_text + rag_block, cited_finding_ids=cited),
            impression=ReportSection(text=impression_text, cited_finding_ids=cited),
            recommendations=ReportSection(text=recs, cited_finding_ids=[]),
            synthetic=True,
            clinically_validated=False,
            rag_citations=used_passages,
            used_passage_ids=used_ids,
            rag_note=(
                "Cited RAG passages are the mock draft's used_passage_ids only "
                "(retrieval similarity score ≠ clinical confidence). Not clinical evidence."
            ),
        )
        return LLMResponse(
            provider_id=self.provider_id,
            model_id=self.model_id,
            model_version=self.model_version,
            report=report,
            raw_text=None,
        )
